using System.Text;

namespace ResearchAgent;

/// <summary>
/// In-memory notebook that stores research notes taken by the agent.
/// </summary>
public sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public string TakeNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (title, content, timestamp) = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {title} (taken at {timestamp:HH:mm:ss UTC}) ---");
            sb.AppendLine(content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

