using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Defines the AI tools available to the research agent.
/// </summary>
public static class ResearchTools
{
    /// <summary>
    /// Creates all tools for the research agent.
    /// </summary>
    public static IList<AITool> Create(Notebook notebook, HttpClient httpClient)
    {
        return
        [
            AIFunctionFactory.Create(
                ([Description("The search query to look up on the web")] string query) =>
                    WebSearchAsync(query, httpClient),
                "web_search",
                "Search the web for information on a topic. Returns relevant search results."),

            AIFunctionFactory.Create(
                ([Description("A short descriptive title for the note")] string title,
                 [Description("The detailed content of the note")] string content) =>
                    notebook.TakeNote(title, content),
                "take_note",
                "Save a research note with a title and content. Use this to record key findings."),

            AIFunctionFactory.Create(
                notebook.GetAllNotes,
                "get_notes",
                "Retrieve all research notes taken so far. Use this to review findings before summarizing."),
        ];
    }

    private static async Task<string> WebSearchAsync(string query, HttpClient httpClient)
    {
        try
        {
            // DuckDuckGo Instant Answer API — free, no API key required
            var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";
            var json = await httpClient.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
                    {
                        var topicUrl = topic.TryGetProperty("FirstURL", out var firstUrl) ? firstUrl.GetString() : "";
                        results.Add($"- {text.GetString()} ({topicUrl})");
                    }
                }
            }

            // Definition
            var definition = root.GetProperty("Definition").GetString();
            if (!string.IsNullOrWhiteSpace(definition))
            {
                results.Add($"Definition: {definition}");
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for \"{query}\". Try a more specific or differently worded query.";
            }

            return $"Search results for \"{query}\":\n\n{string.Join("\n\n", results)}";
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try again or use a different query.";
        }
    }
}

