using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client through MEAI abstraction ---
IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .Build();

// --- Create tools ---
using var httpClient = new HttpClient();
httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

var notebook = new Notebook();
var tools = ResearchTools.Create(notebook, httpClient);

// --- Configure the agent ---
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a thorough research agent. Given a topic, you search the web for
        information and take structured notes on your findings.

        Follow this workflow:
        1. Break the topic into 2-3 specific search queries.
        2. For each query, call web_search and then call take_note to record the
           key facts you found.
        3. After all searches, call get_notes to review your collected research.
        4. Produce a well-organized summary with sections, citing the sources you found.

        Be concise in your notes but thorough in your final summary.
        """,
};

// --- Get the topic from the user ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Run the agent loop ---
var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 15,
    ModelOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
};

var thread = new ChatClientAgentThread();
var userMessage = new ChatMessage(ChatRole.User,
    $"Research the following topic and provide a comprehensive summary: {topic}");

await foreach (var response in agent.InvokeStreamingAsync([userMessage], thread, invokeOptions))
{
    if (!string.IsNullOrEmpty(response.Message.Text))
    {
        // Tool-call steps produce internal messages; only print assistant text
        if (response.Message.Role == ChatRole.Assistant)
        {
            Console.Write(response.Message.Text);
        }
    }
}

Console.WriteLine("\n\n✅ Research complete.");

